parameters.jsCode:
const data = $input.item.json;
const snippets = [];

// Pull short text snippets only, skip images/tokens/metadata
if (data.related_questions) {
  data.related_questions.forEach(q => {
    if (q.snippet) snippets.push(q.snippet);
  });
}
if (data.organic_results) {
  data.organic_results.forEach(r => {
    if (r.snippet) snippets.push(r.snippet);
  });
}

return {
  json: {
    combined_text: snippets.join(' | ')
  }
};

const rawContent = $input.item.json.choices[0].message.content;
const cleaned = rawContent.replace(/```json\s*|```/g, '').trim();

let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = { low_aed: 30, high_aed: 60, unit: "sqft", source_note: "fallback default - parsing failed" };
}

return { json: parsed };

const priceRange = $('Parse Price Range').first().json;
const quotes = $input.all().map(item => item.json);

const VAGUE_KEYWORDS = ['miscellaneous', 'contingency', 'other', 'sundry', 'general'];
const DEPOSIT_RISK_THRESHOLD = 30; // percent

const auditedQuotes = quotes.map(q => {
  let lineItems;
  try {
    lineItems = JSON.parse(q.line_items_json);
  } catch (e) {
    lineItems = [];
  }

  const flags = [];

  // Flag 1: high deposit
  const depositPct = Number(q.deposit_requested_percent);
  if (depositPct > DEPOSIT_RISK_THRESHOLD) {
    flags.push(`HIGH RISK: deposit of ${depositPct}% requested, above the ${DEPOSIT_RISK_THRESHOLD}% norm`);
  }

  // Flag 2: vague line items
  lineItems.forEach(li => {
    const itemLower = (li.item || '').toLowerCase();
    if (VAGUE_KEYWORDS.some(kw => itemLower.includes(kw))) {
      flags.push(`MEDIUM RISK: vague line item "${li.item}" (AED ${li.cost_aed}) lacks a clear breakdown`);
    }
  });

  // Flag 3: total price sanity check vs reference range (using total as rough signal)
  const total = Number(q.total_price_aed);
  const impliedLow = priceRange.low_aed;
  const impliedHigh = priceRange.high_aed;
  // Simple total-based sanity note (not a strict per-sqft check, since job size varies)
  let priceNote = 'within a reasonable range for the described scope';
  if (total < impliedLow * 0.3) {
    priceNote = 'notably low for the described scope - verify quality/material specification isn\'t downgraded';
    flags.push(`LOW-PRICE FLAG: total (AED ${total}) is well below typical reference pricing`);
  }

  const riskLevel = flags.some(f => f.startsWith('HIGH')) ? 'HIGH'
    : flags.some(f => f.startsWith('MEDIUM') || f.startsWith('LOW-PRICE')) ? 'MEDIUM'
    : 'LOW';

  return {
    vendor_name: q.vendor_name,
    reference_code: q.reference_code,
    total_price_aed: total,
    deposit_requested_percent: depositPct,
    estimated_days: q.estimated_days,
    line_items: lineItems,
    risk_level: riskLevel,
    flags: flags.length ? flags : ['No issues detected - pricing and terms appear standard'],
    price_note: priceNote
  };
});

return auditedQuotes.map(q => ({ json: q }));

parameters.text:
=You are reviewing 3 audited vendor quotes for a home renovation job. Here is the data: {{ JSON.stringify($input.all().map(i => i.json)) }}

Rank the vendors from best to worst, weighing both total_price_aed and risk_level (a HIGH risk flag should weigh heavily against an otherwise-cheap price). Identify the top-ranked vendor. If the top vendor's total_price_aed exceeds 4000 AED, draft a brief, polite counter-offer message asking if they can match a target price of 4000 AED, citing that you have competitive quotes.

Respond ONLY with valid JSON in this exact shape, no extra text or markdown formatting:
{
  "ranking": [{"vendor_name":"","total_price_aed":0,"risk_level":"","reasoning":""}],
  "top_vendor_name": "",
  "needs_counter_offer": true,
  "counter_offer_subject": "",
  "counter_offer_body": ""
}

parameters.jsCode:
const rawContent = $input.first().json.output;
const cleaned = rawContent.replace(/```json\s*|```/g, '').trim();

let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = { ranking: [], top_vendor_name: "unknown", needs_counter_offer: false, counter_offer_subject: "", counter_offer_body: "" };
}

return [{ json: parsed }];

const decision = $('Parse Agent Decision').first().json;
const vendors = $input.all().map(i => i.json);

const match = vendors.find(v =>
  v.name.toLowerCase().includes(decision.top_vendor_name.toLowerCase()) ||
  decision.top_vendor_name.toLowerCase().includes(v.name.toLowerCase())
);

let cleanedBody = decision.counter_offer_body || '';
cleanedBody = cleanedBody
  .replace(/\[Your Name\]/gi, 'Fazil')
  .replace(/\[Your Contact Information\]/gi, '')
  .replace(/\[Your Position.*?\]/gi, '')
  .replace(/\[Contact Information\]/gi, '')
  .replace(/\n{3,}/g, '\n\n'); // clean up any extra blank lines left behind

return [{
  json: {
    ...decision,
    top_vendor_email: match ? match.email : null,
    counter_offer_body: cleanedBody
  }
}];

